const techRows = $('Lay Technical Signals').all().map(i => i.json);
const symbolList = techRows.map(r => r.symbol);

const CHUNK_SIZE = 5;
const chunks = [];
for (let i = 0; i < symbolList.length; i += CHUNK_SIZE) {
  chunks.push(symbolList.slice(i, i + CHUNK_SIZE));
}

return chunks.map((chunk, idx) => ({ json: { chunk_index: idx, symbols: chunk } }));

const chunk = $('Loop Over Chunks').first().json;
const symbolList = chunk.symbols;

const techRows = $('Lay Technical Signals').all().map(i => i.json);
const sentimentRow = $('Lay Sentiment Gan Nhat').first() ? $('Lay Sentiment Gan Nhat').first().json : null;
const macroRow = $('Lay Macro Gan Nhat').first() ? $('Lay Macro Gan Nhat').first().json : null;

const techBySymbol = {};
for (const t of techRows) techBySymbol[t.symbol] = t;

const sentimentText = sentimentRow
  ? `${sentimentRow.signal} (confidence ${sentimentRow.confidence}) - ${sentimentRow.reason}`
  : 'Chua co danh gia Sentiment';
const macroText = macroRow
  ? `${macroRow.signal} (confidence ${macroRow.confidence}) - ${macroRow.reason}`
  : 'Chua co danh gia Macro';

const techLines = symbolList.map(sym => {
  const t = techBySymbol[sym];
  if (!t) return `${sym}: (chua co du lieu Technical)`;
  return `${sym}: Ban (Technical Agent) da ket luan ${t.signal} (confidence ${t.confidence}) - Ly do: ${t.reason}`;
});

const prompt = `Ban dang dong vai Technical Agent. Ban vua dua ra nhan dinh ky thuat rieng cho cac coin sau:\n${techLines.join('\n')}\n\nBAY GIO, 2 thanh vien khac trong hoi dong dau tu (Investment Committee) trinh bay y kien khac ve BOI CANH CHUNG cua thi truong:\n- Sentiment Agent (tam ly thi truong): ${sentimentText}\n- Macro Agent (vi mo kinh te): ${macroText}\n\nHay XEM XET LAI tung nhan dinh ky thuat cua ban duoi anh huong cua 2 y kien nay:\n- Neu boi canh chung UNG HO quan diem ky thuat cua ban, hay GIU NGUYEN hoac TANG do tin cay.\n- Neu boi canh chung MAU THUAN voi quan diem ky thuat cua ban, hay CAN NHAC GIAM do tin cay (khong nhat thiet phai doi tin hieu, nhung phai the hien su can nhac that su).\n\nTra loi DUY NHAT mot JSON array, khong markdown, dung format:\n[{"symbol": "BTCUSDT", "signal": "BUY|SELL|HOLD", "confidence": 0-100, "reason": "lap luan cua ban SAU KHI da can nhac phan bien tu Sentiment va Macro"}]\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;

return [{ json: { prompt, symbol_list: symbolList } }];

const raw = $input.first().json;
const symbolList = $('Build Debate Prompt').first().json.symbol_list;

let contentText = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  contentText = raw.choices[0].message.content || '';
}
const cleaned = contentText.replace(/```json|```/g, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = []; }

if (parsed && !Array.isArray(parsed) && typeof parsed === 'object') {
  parsed = Object.entries(parsed).map(([key, val]) => ({
    symbol: (val && val.symbol) || key,
    signal: val ? val.signal : undefined,
    confidence: val ? val.confidence : undefined,
    reason: val ? val.reason : undefined
  }));
}

if (!Array.isArray(parsed) || parsed.length === 0) {
  const techRows = $('Lay Technical Signals').all().map(i => i.json);
  const techBySymbol = {};
  for (const t of techRows) techBySymbol[t.symbol] = t;
  parsed = symbolList.map(symbol => {
    const t = techBySymbol[symbol] || {};
    return { symbol, signal: t.signal || 'HOLD', confidence: t.confidence || 0, reason: 'debate_parse_error: giu nguyen quan diem goc' };
  });
}

return parsed.map(p => {
  let conf = parseInt(p.confidence, 10);
  if (isNaN(conf)) conf = null;
  return { json: {
    symbol: p.symbol,
    debated_signal: (p.signal || 'HOLD').toUpperCase(),
    debated_confidence: conf,
    debate_reason: p.reason || ''
  } };
});

const chunk = $('Loop Over Chunks').first().json;
const symbolList = chunk.symbols;
const debated = $input.all().map(i => i.json);

const sentimentRow = $('Lay Sentiment Gan Nhat').first() ? $('Lay Sentiment Gan Nhat').first().json : null;
const macroRow = $('Lay Macro Gan Nhat').first() ? $('Lay Macro Gan Nhat').first().json : null;

const sentimentText = sentimentRow ? `${sentimentRow.signal} (confidence ${sentimentRow.confidence})` : 'khong ro';
const macroText = macroRow ? `${macroRow.signal} (confidence ${macroRow.confidence})` : 'khong ro';

const lines = debated.map(d => `${d.symbol}: SAU TRANH LUAN, Technical Agent ket luan ${d.debated_signal} (confidence ${d.debated_confidence}) - ${d.debate_reason}`);

const prompt = `Ban la Investment Committee (Manager AI) cua mot quy dau tu crypto nho.\nDuoi day la ket luan CUOI CUNG cua Technical Agent, SAU KHI da tranh luan va can nhac ca boi canh Sentiment (${sentimentText}) va Macro (${macroText}):\n\n${lines.join('\n')}\n\nHay dua ra QUYET DINH DAU TU cuoi cung cho tung coin.\n\nTra loi DUY NHAT mot JSON array, khong markdown, dung format:\n[{"symbol": "BTCUSDT", "final_signal": "BUY|SELL|HOLD", "final_confidence": 0-100, "reason": "quyet dinh cuoi cung, tom tat qua trinh tranh luan"}]\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;

return [{ json: { prompt, symbol_list: symbolList, debated_map: debated } }];

const raw = $input.first().json;
const symbolList = $('Build Final Synthesis Prompt').first().json.symbol_list;
const debatedMap = $('Build Final Synthesis Prompt').first().json.debated_map;
const debatedBySymbol = {};
for (const d of debatedMap) debatedBySymbol[d.symbol] = d;

const techRows = $('Lay Technical Signals').all().map(i => i.json);
const techBySymbol = {};
for (const t of techRows) techBySymbol[t.symbol] = t;

const sentimentRow = $('Lay Sentiment Gan Nhat').first() ? $('Lay Sentiment Gan Nhat').first().json : null;
const macroRow = $('Lay Macro Gan Nhat').first() ? $('Lay Macro Gan Nhat').first().json : null;

let contentText = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  contentText = raw.choices[0].message.content || '';
}
const cleaned = contentText.replace(/```json|```/g, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = []; }

if (parsed && !Array.isArray(parsed) && typeof parsed === 'object') {
  parsed = Object.entries(parsed).map(([key, val]) => ({
    symbol: (val && val.symbol) || key,
    final_signal: val ? val.final_signal : undefined,
    final_confidence: val ? val.final_confidence : undefined,
    reason: val ? val.reason : undefined
  }));
}

if (!Array.isArray(parsed) || parsed.length === 0) {
  parsed = symbolList.map(symbol => {
    const d = debatedBySymbol[symbol] || {};
    return { symbol, final_signal: d.debated_signal || 'HOLD', final_confidence: d.debated_confidence || 0, reason: 'final_parse_error: dung ket qua tranh luan' };
  });
}

return parsed.map(p => {
  const t = techBySymbol[p.symbol] || {};
  const d = debatedBySymbol[p.symbol] || {};
  let conf = parseInt(p.final_confidence, 10);
  if (isNaN(conf)) conf = null;
  return { json: {
    symbol: p.symbol,
    technical_signal: t.signal || null,
    technical_confidence: t.confidence || null,
    sentiment_signal: sentimentRow ? sentimentRow.signal : null,
    macro_signal: macroRow ? macroRow.signal : null,
    debated_technical_signal: d.debated_signal || null,
    debated_technical_confidence: d.debated_confidence || null,
    debate_reason: d.debate_reason || '',
    final_signal: (p.final_signal || 'HOLD').toUpperCase(),
    final_confidence: conf,
    reason: p.reason || ''
  } };
});
